  function translateMain(s) {
    if (!/[가-힣]/.test(s)) return s;
    for (const [re, rep] of MAIN) {
      const m = s.match(re);
      if (m) return typeof rep === 'function' ? rep(...m) : s.replace(re, rep);
    }
    return s;
  }

